            (), (0,), (LCA_MAX_NODES + 1,), (1, 0, 0, 0),
            (2, 0, 2, 0, 1), (2, 0, 1, 0, 2), (2, 0, 0, 0, 1),
            (3, 0, 1, 0, 1, 0, 2), (4, 0, 1, 1, 2, 2, 0, 0, 3),
