            (), (0,), (0, 1), (2, 1, 1, 9), (0, 0, 1),
            (1, KTH_ELEMENT_FINDER_MAX_N + 1, 1), (0, 3, 0, 1, 2, 3),
            (1, 3, 4, 1, 2, 3), (0, 3, 2, 1, 2),
