                for edge_index, (left, right) in enumerate(edge_pairs):
                    if edge_selection & (1 << edge_index):
                        masks[left] |= 1 << right
                        masks[right] |= 1 << left
                values = (vertex_count, *masks)
                cases[values] = oracle(algorithm, list(values))
