            (3, 2, 0, 1, 5, 1, 2, 6, 1, 0, 0, 2, 5),
            (2, 0, 1, 0, 0, 2, 1),
            (2, 0, 1, 0, 1, 1, 0),
            (2, 0, 1, 0, 0, 1, UNDIRECTED_GRAPH_MIN_WEIGHT - 1),
            (2, 0, 1, 1, 0, 1, 1),
