                if seen_keys and rng_immutable_hash_map.randrange(3) == 0:
                    key = rng_immutable_hash_map.choice(seen_keys)
                elif rng_immutable_hash_map.randrange(3) == 0:
                    key = rng_immutable_hash_map.choice(key_bounds)
