            values = [count, *(rng.randint(-EQUAL_LOUDNESS_SAMPLE_LIMIT, EQUAL_LOUDNESS_SAMPLE_LIMIT)
                               for _ in range(count))]
            cases[tuple(values)] = oracle(algorithm, values)
