            (), (-1,), (MAX_GOOD_PAIRS_N + 1,),
            (3, 1, 1), (1, 0, 0),
            (1, MIN_GOOD_PAIRS_VALUE - 1),
            (1, MAX_GOOD_PAIRS_VALUE + 1),
            (1, I64_MIN), (1, I64_MAX),
