        edge_cells = edge_matrix[2:]
        for target in (edge_cells[0], edge_cells[-1], MIN_SADDLEBACK_SEARCH_VALUE,
                       MAX_SADDLEBACK_SEARCH_VALUE):
            values = (4, 5, target, *edge_cells)
            cases[values] = oracle(algorithm, list(values))

